// ==========================================
// FUNZIONI DEL GIOCO
// ==========================================

function initializeRacingGame(lobbyId, players, settings) {
    console.log(`🏎️ Inizializzazione Racing per lobby ${lobbyId}`, settings);

    const isSingleMode = settings.mode === 'single';
    let selectedTracks = [];

    if (isSingleMode) {
        // Cerca la pista specifica scelta dall'host
        const track = TRACKS.find(t => t.name === settings.trackName) || TRACKS[0];
        selectedTracks = [track];
    } else {
        // Modalità Campionato
        const requestedTracks = settings.numTracks || 3;
        let shuffledTracks = [...TRACKS].sort(() => Math.random() - 0.5);
        selectedTracks = shuffledTracks.slice(0, requestedTracks);
    }

    const game = {
        lobbyId,
        gameId: 'racing',
        players: [...players],
        playersState: {},
        tracks: selectedTracks,
        currentTrackIndex: 0,
        cumulativeTimes: {},
        tileSize: TILE_SIZE,
        podium: [],
        isActive: false,
        isSingleMode: isSingleMode, // Salva la modalità nello stato del gioco
        startTime: null,
        loopInterval: null
    };

    players.forEach(p => {
        game.cumulativeTimes[p] = 0;
    });

    resetPlayersForCurrentTrack(game);
    activeGames.set(lobbyId, game);
    return game;
}

// Funzione helper per riposizionare le auto ad ogni nuova gara
function resetPlayersForCurrentTrack(game) {
    const track = game.tracks[game.currentTrackIndex];
    game.podium = []; // Svuota il podio della singola gara

    game.players.forEach(p => {
        game.playersState[p] = {
            color: p,
            x: track.spawnX,
            y: track.spawnY,
            angle: track.angle,
            inputs: { w: false, a: false, s: false, d: false },
            progress: 0,
            finished: false,
            place: null,
            time: null,
            lastActiveTime: Date.now(),
            dnf: false
        };
    });
}

function runGameLoop(io, lobbyId) {
    const game = activeGames.get(lobbyId);
    if (!game) return;

    const baseSpeed = 24; // Velocità massima su asfalto
    const currentTrackMap = game.tracks[game.currentTrackIndex].map;

    game.loopInterval = setInterval(() => {
        // [FIX CRITICO]: Se la partita non esiste più in memoria, distruggi il loop fantasma!
        if (!activeGames.has(lobbyId)) {
            clearInterval(game.loopInterval);
            return;
        }

        if (!game.isActive) return;

        let everyoneFinished = true;

        for (const [color, pState] of Object.entries(game.playersState)) {
            if (pState.finished) continue;

            // --- INIZIO NUOVO CODICE AFK ---
            // 1. Se sta premendo un tasto, resetta il timer di inattività
            if (pState.inputs.w || pState.inputs.a || pState.inputs.s || pState.inputs.d) {
                pState.lastActiveTime = Date.now();
            }

            // 2. Controlla se ha superato il tempo limite (AFK)
            if (Date.now() - pState.lastActiveTime > AFK_TIMEOUT_MS) {
                pState.finished = true;
                pState.dnf = true;
                pState.progress = 3;
                pState.time = 9999999; // Penalità

                game.podium.push({
                    color: color,
                    time: pState.time,
                    isRecord: false,
                    dnf: true
                });

                // Avvisa gli altri giocatori in chat
                io.to(lobbyId).emit('message', {
                    message: `💤 Il giocatore ${color} è stato squalificato per inattività ed è stato rimosso dalla lobby.`,
                    type: 'system'
                });

                // --- INIZIO RIMOZIONE DALLA LOBBY ---
                const lobby = lobbies.get(lobbyId);
                if (lobby) {
                    // Rimuovi dalla lobby generale
                    lobby.players = lobby.players.filter(c => c !== color);
                    users.delete(color);
                }

                // Rimuovi anche dall'array dei giocatori della gara in corso
                game.players = game.players.filter(c => c !== color);

                // Spara l'evento "playerKicked", il frontend farà il redirect alla home
                io.to(lobbyId).emit('playerKicked', color);
                // --- FINE RIMOZIONE DALLA LOBBY ---

                continue; // Passa al prossimo giocatore
            }
            // --- FINE NUOVO CODICE AFK ---

            everyoneFinished = false;

            // --- HITBOX SIMMETRICA CENTRATA ---
            // Usiamo dimensioni un po' più piccole dell'immagine reale (86x40)
            // per rendere il gioco più fluido e perdonare i piccoli sfioramenti
            const hitBoxWidth = 50;
            const hitBoxHeight = 24;

            let left = pState.x - (hitBoxWidth / 2);
            let right = pState.x + (hitBoxWidth / 2);
            let top = pState.y - (hitBoxHeight / 2);
            let bottom = pState.y + (hitBoxHeight / 2);

            // 1. DETERMINA LA SUPERFICIE ATTUALE PER CALCOLARE LA VELOCITÀ
            let currentPoints = [
                { x: left, y: top },
                { x: right, y: top },
                { x: left, y: bottom },
                { x: right, y: bottom }
            ];

            let speedMultiplier = 1.0; // Di base 100% della velocità

            for (let pt of currentPoints) {
                let col = Math.floor(pt.x / game.tileSize);
                let row = Math.floor(pt.y / game.tileSize);

                if (row >= 0 && row < currentTrackMap.length && col >= 0 && col < currentTrackMap[0].length) {
                    let tile = currentTrackMap[row][col];
                    if (tile === 4) {
                        // Se tocca la ghiaia (4), la velocità scende al 55%
                        speedMultiplier = Math.min(speedMultiplier, 0.55);
                    }
                }
            }

            // Applica la velocità modificata
            let actualSpeed = baseSpeed * speedMultiplier;

            let moveX = 0;
            let moveY = 0;

            if (pState.inputs.w) moveY -= 1;
            if (pState.inputs.s) moveY += 1;
            if (pState.inputs.a) moveX -= 1;
            if (pState.inputs.d) moveX += 1;

            let dx = 0;
            let dy = 0;

            // Se c'è movimento, normalizza il vettore
            if (moveX !== 0 || moveY !== 0) {
                const magnitude = Math.sqrt(moveX * moveX + moveY * moveY);
                const normalizedX = moveX / magnitude;
                const normalizedY = moveY / magnitude;

                dx = normalizedX * actualSpeed;
                dy = normalizedY * actualSpeed;
            }

            let nextX = pState.x + dx;
            let nextY = pState.y + dy;

            // Calcola i 4 angoli della PROSSIMA posizione
            let nextLeft = nextX - (hitBoxWidth / 2);
            let nextRight = nextX + (hitBoxWidth / 2);
            let nextTop = nextY - (hitBoxHeight / 2);
            let nextBottom = nextY + (hitBoxHeight / 2);

            // 2. CONTROLLA COSA C'È NELLA PROSSIMA POSIZIONE
            let nextPoints = [
                { x: nextLeft, y: nextTop },
                { x: nextRight, y: nextTop },
                { x: nextLeft, y: nextBottom },
                { x: nextRight, y: nextBottom }
            ];

            let canMove = true;
            let hitSector1 = false;
            let hitSector2 = false;
            let isOnFinishLine = false;

            for (let pt of nextPoints) {
                let col = Math.floor(pt.x / game.tileSize);
                let row = Math.floor(pt.y / game.tileSize);

                // FUORI MAPPA: Blocca il movimento
                if (row < 0 || row >= currentTrackMap.length || col < 0 || col >= currentTrackMap[0].length) {
                    canMove = false;
                    break;
                }

                let tile = currentTrackMap[row][col];

                // MURI (5) ED ERBA (0): Blocca il movimento!
                if (tile === 0 || tile === 5) {
                    canMove = false;
                    break;
                }

                if (tile === 6) hitSector1 = true;
                if (tile === 3) hitSector2 = true;
                if (tile === 2) isOnFinishLine = true;
            }

            if (canMove) {
                pState.x = nextX;
                pState.y = nextY;

                if (hitSector1 && pState.progress === 0) pState.progress = 1;
                if (hitSector2 && pState.progress === 1) pState.progress = 2;

                if (isOnFinishLine && pState.progress === 2) {
                    pState.finished = true;
                    pState.progress = 3;

                    const lapTimeMs = Date.now() - game.startTime;
                    pState.time = lapTimeMs;

                    const trackName = currentTrackMap === game.tracks[0].map ? game.tracks[0].name : game.tracks[game.currentTrackIndex].name;
                    const isRecord = leaderboard.isTop10Record(trackName, lapTimeMs);

                    game.podium.push({
                        color: color,
                        time: lapTimeMs,
                        isRecord: isRecord
                    });

                    pState.place = game.podium.length;

                    const mins = Math.floor(lapTimeMs / 60000);
                    const secs = Math.floor((lapTimeMs % 60000) / 1000);
                    const ms = lapTimeMs % 1000;
                    const formatted = `${mins}:${secs.toString().padStart(2, '0')}.${ms.toString().padStart(3, '0')}`;

                    if (isRecord) {
                        io.to(lobbyId).emit('message', {
                            message: `🚨 TEMPO DA TOP 10! ${color} ha chiuso in ${formatted}! 🚨`,
                            type: 'success'
                        });
                    } else {
                        io.to(lobbyId).emit('message', {
                            message: `🏁 ${color} ha finito la gara in ${formatted}`,
                            type: 'success'
                        });
                    }
                }
            }

            if (dx !== 0 || dy !== 0) {
                let targetAngle = Math.atan2(dy, dx) * (180 / Math.PI);
                let diff = targetAngle - pState.angle;
                while (diff <= -180) diff += 360;
                while (diff > 180) diff -= 360;
                pState.angle += diff;
            }
        }

        io.to(lobbyId).emit('racingStateUpdate', game.playersState);

        if (everyoneFinished && game.players.length > 0) {
            handleRaceEnd(io, lobbyId);
        }
    }, 1000 / 60);
}

// GESTIONE FINE GARA E PASSAGGIO ALLA PROSSIMA
function handleRaceEnd(io, lobbyId) {
    const game = activeGames.get(lobbyId);
    if (!game) return;

    game.isActive = false;
    clearInterval(game.loopInterval);

    game.podium.forEach(entry => {
        game.cumulativeTimes[entry.color] += entry.time;
    });

    const isFinalRace = game.currentTrackIndex >= game.tracks.length - 1;
    const cumulativePodium = Object.keys(game.cumulativeTimes).map(color => {
        return {
            color: color,
            totalTime: game.cumulativeTimes[color],
            lastRaceTime: game.podium.find(p => p.color === color)?.time || 0
        };
    }).sort((a, b) => a.totalTime - b.totalTime);

    const singleRacePodium = [...game.podium];
    const someoneGotRecord = singleRacePodium.some(p => p.isRecord);
    const trackName = game.tracks[game.currentTrackIndex].name;
    const mapTop3 = leaderboard.getTop10(trackName).slice(0, 3);

    // Recupera la lobby per l'host
    const lobby = lobbies.get(lobbyId);
    const hostColor = lobby ? lobby.host : null;

    io.to(lobbyId).emit('raceEnded', {
        podium: cumulativePodium,
        singleRacePodium: singleRacePodium,
        mapTop3: mapTop3,
        isFinal: isFinalRace,
        trackName: trackName,
        isSingleMode: game.isSingleMode,
        hostColor: hostColor // <-- Aggiunto l'host!
    });

    // Se è modalità singola, FERMIAMO IL TEMPO. Spetterà all'host riavviare o uscire.
    if (game.isSingleMode) {
        return; // Non fare nulla, aspetta l'evento socket 'restartRace' o 'forceReturnToLobby'
    }

    // Logica originale per il Campionato
    if (isFinalRace) {
        setTimeout(() => {
            activeGames.delete(lobbyId);
            // [FIX]: Il frontend ascolta "redirectAllToLobby", non "returnToLobby"!
            io.to(lobbyId).emit('redirectAllToLobby');
        }, 15000);
    } else {
        const delay = someoneGotRecord ? 12000 : 7000;
        io.to(lobbyId).emit('message', { message: `Prossima gara tra ${delay / 1000} secondi...`, type: 'system' });
        setTimeout(() => { loadNextTrack(io, lobbyId); }, delay);
    }
}

function loadNextTrack(io, lobbyId) {
    const game = activeGames.get(lobbyId);
    if (!game) return;

    game.currentTrackIndex++;
    resetPlayersForCurrentTrack(game);

    const nextTrack = game.tracks[game.currentTrackIndex];

    io.to(lobbyId).emit('racingSetup', {
        playersState: game.playersState,
        trackMap: nextTrack.map,
        tileSize: game.tileSize,
        trackName: nextTrack.name,
        isSingleMode: game.isSingleMode, // <-- FIX 1/3 MODALITA' SINGOLA
        totalLaps: 1                     // <-- FIX 1/3 MODALITA' SINGOLA
    });

    // Fai partire la gara automaticamente!
    setTimeout(() => {
        startRace(io, lobbyId);
    }, 3000);
}

function updatePlayerInput(lobbyId, playerColor, inputs) {
    const game = activeGames.get(lobbyId);
    if (game && game.playersState[playerColor] && game.isActive) game.playersState[playerColor].inputs = inputs;
}

function startRace(io, lobbyId) {
    const game = activeGames.get(lobbyId);
    if (!game) return;

    game.isActive = true;
    game.startTime = Date.now(); // Resetta e avvia il timer!

    for (const pState of Object.values(game.playersState)) {
        pState.lastActiveTime = Date.now();
    }

    io.to(lobbyId).emit('raceStarted', {
        trackName: game.tracks[game.currentTrackIndex].name
    });

    runGameLoop(io, lobbyId);
}

function restartRace(io, lobbyId) {
    const game = activeGames.get(lobbyId);
    if (!game) return;

    // [FIX]: Sincronizza l'array della gara leggendo chi c'è DAVVERO in lobby ora
    const lobby = lobbies.get(lobbyId);
    if (lobby) {
        lobby.players.forEach(pColor => {
            if (!game.players.includes(pColor)) {
                game.players.push(pColor);
            }
            if (game.cumulativeTimes[pColor] === undefined) {
                game.cumulativeTimes[pColor] = 0;
            }
        });
    }

    // Resetta i tempi cumulativi per non falsare il tabellone se si riavvia
    Object.keys(game.cumulativeTimes).forEach(p => {
        game.cumulativeTimes[p] = 0;
    });

    resetPlayersForCurrentTrack(game);

    io.to(lobbyId).emit('racingSetup', {
        playersState: game.playersState,
        trackMap: game.tracks[0].map,
        tileSize: game.tileSize,
        trackName: game.tracks[0].name,
        isSingleMode: game.isSingleMode,
        totalLaps: 1
    });

    io.to(lobbyId).emit('message', { message: 'La gara è stata riavviata! Preparatevi...', type: 'system' });

    setTimeout(() => {
        startRace(io, lobbyId);
    }, 3000);
}

// AGGIORNA l'export alla fine del file!
module.exports = { initializeRacingGame, updatePlayerInput, startRace, restartRace };